-- A-Level Politics Flashcards — Edexcel (9PL0)
-- Generated for the RAG Learning study app from the notes and question banks.
-- One INSERT per topic. card_order restarts at 1 within each topic.
--
-- SAFE TO RE-RUN: the DELETE below clears any previous Politics/Edexcel/alevel
-- rows first, so running this file twice does not duplicate cards.
--
-- WHAT IS HERE: 28 topics x 8 cards = 224. All 28 are loaded, including BOTH
-- Component 3 routes (3A USA and 3B Global). A student sits only one route,
-- and the flashcards page filters by the topics a student has, so loading
-- both costs nothing and lets a student who switches route keep working.
--
-- TOPIC IDS match topics-config.js and the question banks exactly. They are
-- the join key, so do not renumber them here without renumbering everywhere.

-- ---------------------------------------------------------------
-- Schema: add 'level' column if not present (idempotent).
-- Politics is A-Level only, so every row below is level = 'alevel'.
-- ---------------------------------------------------------------
ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS level TEXT DEFAULT 'alevel'
  CHECK (level IN ('gcse','as','alevel'));

-- ---------------------------------------------------------------
-- Clear any existing Politics/Edexcel cards so this file is re-runnable.
-- Note this touches ONLY exam_board = 'Edexcel'; the AQA Politics cards
-- loaded by flashcards-politics-alevel-content.sql are untouched.
-- ---------------------------------------------------------------
DELETE FROM flashcards
 WHERE subject = 'Politics' AND exam_board = 'Edexcel' AND level = 'alevel';


